def load_logs_setting(pull, run, m, S):
    """the rule logs of a run at setting S. Both settings use --rule-every 5, so both logs (rule_log and rule_log_mid) are needed, by the model reader's own load_logs. With no --rule-every a run writes the first
    log only; then the first log is needed and a mid log is read only if it lies on disk (kept from the reader of card ADD113)."""
    if SPEC[S]["every"] is not None:
        return MD.load_logs(pull, run, m)
    d = os.path.join(pull, "I10%s_s%d" % (run, m), "ticks")
    first = os.path.join(d, "rule_log_I10%s_s%d.npz" % (run, m))
    mid = os.path.join(d, "rule_log_mid_I10%s_s%d.npz" % (run, m))
    if not os.path.isfile(first):
        raise SystemExit("REFUSED: no rule log %s" % first)
    zs = []
    for p in [first] + ([mid] if os.path.isfile(mid) else []):
        with np.load(p, allow_pickle=False) as z:
            zs.append({k: z[k] for k in z.files})
    return zs


def rows4(logs):
    """-> (ci, j, present, g_src) over the logs of one rollout; tolerant of a log with no c_src column (the label form need not log a closing input)"""
    cols = {k: [] for k in ("ci", "j", "present", "g_src")}
    for z in logs:
        for k in cols:
            cols[k].append(np.asarray(z[k]))
    return (np.concatenate(cols["ci"]).astype(np.int64), np.concatenate(cols["j"]).astype(np.int64), np.concatenate(cols["present"]).astype(bool),
            np.concatenate(cols["g_src"]).astype(np.float64))


def pl_check(rows, JL):
    """control e7, planted-join runs. rows = (ci, j, present, g_src) of one rollout; JL = {lead_valid, lead_gap, off, n} of JLE.npz. A logged step (ci, j) maps to the join row off[ci] + j (ci indexes the clip
    order of the join: an open definition, see PRESATTR_READ_DEFS.md). On every logged step with a lead the gap the rule received equals lead_gap of that row within 1e-3 m; the logged steps with a lead are the
    logged steps whose join row is valid by the rule's own test for a join (marking 1, gap finite, 0 <= gap <= 60 m)."""
    ci, j, pres, g = rows
    off, n = np.asarray(JL["off"]).astype(np.int64), np.asarray(JL["n"]).astype(np.int64)
    lv, lg = np.asarray(JL["lead_valid"]), np.asarray(JL["lead_gap"], dtype=np.float64)
    ok_map = (ci >= 0) & (ci < len(n))
    ok_map[ok_map] = (j[ok_map] >= 0) & (j[ok_map] < n[ci[ok_map]])
    row = np.zeros(len(ci), np.int64)
    row[ok_map] = off[ci[ok_map]] + j[ok_map]
    gj = np.where(ok_map, lg[row], np.nan)
    valid = ok_map & (lv[row] == 1) & np.isfinite(gj) & (gj >= 0.0) & (gj <= GAP_MAX_M)
    n_unmapped = int((~ok_map).sum())
    n_extra = int((pres & ~valid).sum())                 # a lead in the log where the join gives none
    n_miss = int((~pres & valid).sum())                  # no lead in the log where the join gives one
    both = pres & valid
    n_gap_bad = int((np.abs(g[both] - gj[both]) > TOL_PL).sum()) if both.any() else 0
    n_gap_nan = int((~np.isfinite(g[both])).sum()) if both.any() else 0
    n_lead = int(pres.sum())
    bad = []
    if n_lead == 0:
        bad.append("no logged step with a lead")
    if n_unmapped:
        bad.append("%d logged steps map to no row of the join (clip index or frame out of range)" % n_unmapped)
    if n_extra or n_miss:
        bad.append("%d of %d logged steps disagree on the lead: %d with a lead in the log that the planted join does not give (marking, finiteness or 0 to 60 m), %d with no lead in the log where it gives one"
                   % (n_extra + n_miss, len(ci), n_extra, n_miss))
    if n_gap_bad or n_gap_nan:
        bad.append("%d lead steps whose logged gap differs from the lead_gap of the planted join by more than %g m (%d not finite)" % (n_gap_bad + n_gap_nan, TOL_PL, n_gap_nan))
    return {"PASS": not bad, "failures": bad, "n_rows": int(len(ci)), "n_lead_rows": n_lead, "n_join_valid_rows": int(valid.sum()), "n_unmapped": n_unmapped, "n_lead_not_in_join": n_extra,
            "n_join_lead_not_in_log": n_miss, "n_gap_bad": n_gap_bad, "share_of_rule_steps_with_a_lead": (n_lead / len(ci)) if len(ci) else None}


def margin_file(a, arm):
    return os.path.join(a.margin_dir, MARGIN_FILES[arm] + ".npz")


def rule_checks(a):
    """-> per-rollout dict (key S_arm_s<m>) of the rule-log checks of the eight new rollouts: the model reader's w2_one against the scaled gap file of the arm (as control b2 of card ADD111); the gap the
    reader itself logs, for the lead steps where the file has no output, comes from the rule log of the reference run RR of the setting at the same model seed; the rule log meta names the hash of the
    scaled file and the closing switch."""
    per = {}
    for S, arm in new_pairs():
        gf = margin_file(a, arm)
        for m in SEEDS:
            key = "%s_%s_s%d" % (S, arm, m)
            try:
                if not os.path.isfile(gf):
                    per[key] = {"PASS": False, "failures": ["no scaled gap file %s" % gf]}
                    continue
                gref = MD.gapfile_ref(gf)
                fsha = sha_file(gf)
                logs = load_logs_setting(a.pull, run_name(S, arm), m, S)
                ref_logs = load_logs_setting(a.pull, run_name(S, "RR"), m, S)
                v0 = MD.lead_multi(MD.rows_of(ref_logs))
                meta = MD.meta_of(logs[0])
                r = MD.w2_one(MD.rows_of(logs), gref, v0, meta_expect={"vis_closing": 1}, meta=meta)
                ms = str(meta.get("vis_gap_file_sha256") or "").lower()
                if not (len(ms) >= 16 and (fsha.startswith(ms) or ms.startswith(fsha))):
                    r["failures"] = list(r.get("failures", [])) + ["rule log meta names the gap file hash %s, the scaled file on disk has %s" % (ms[:16] or None, fsha[:16])]
                    r["PASS"] = False
                per[key] = r
            except (SystemExit, OSError, ValueError, KeyError) as ex:
                per[key] = {"PASS": False, "failures": ["cannot read the rollout, its reference or its gap file: %s: %s" % (type(ex).__name__, ex)]}
    return per


def _hash_match(x, y):
    x, y = str(x or "").lower(), str(y or "").lower()
    return len(x) >= 16 and len(y) >= 16 and (x.startswith(y) or y.startswith(x))


def ctl_e0(rec, sha_base, shas):
    """e0 (control k0 of card ADD117) scaled gap files: the record GAPMARGIN_GAPFILES_RECORD.json has pass_k0 true, the scale of one gave the base arrays, every clause of both files is true, and the base
    file and both scaled files on disk have the hashes the record holds; the base file is the one of card ADD106 (sha256 begins 55de2f7c). shas {arm: sha256 of its scaled file on disk}."""
    bad = []
    rec = rec if isinstance(rec, dict) else {}
    if rec.get("pass_k0") is not True:
        bad.append("the record of the scaled gap files has pass_k0 %s" % rec.get("pass_k0"))
    if rec.get("scale_one_gives_the_base_arrays") is not True:
        bad.append("the record does not say that the scale of one gives the base arrays")
    want_b = (rec.get("base") or {}).get("sha256")
    if not sha_base or not want_b or str(sha_base).lower() != str(want_b).lower():
        bad.append("the base gap file on disk has sha256 %s, the record holds %s" % ((sha_base or "none")[:16], str(want_b or "none")[:16]))
    if not str(sha_base or "").startswith("55de2f7c"):
        bad.append("the base gap file is not the one of card ADD106 (sha256 %s)" % (sha_base or "none")[:16])
    newly = {}
    for arm in MARGIN_ARMS:
        nm = MARGIN_FILES[arm]
        cl = (rec.get("clauses") or {}).get(nm)
        if not isinstance(cl, dict) or not cl or not all(v is True for v in cl.values()):
            bad.append("%s: the clauses of the record are not all true" % nm)
        f = (rec.get("files") or {}).get(nm) or {}
        got = (shas or {}).get(arm)
        if not got or not f.get("sha256") or str(got).lower() != str(f.get("sha256")).lower():
            bad.append("%s on disk has sha256 %s, the record holds %s" % (nm, (got or "none")[:16], str(f.get("sha256") or "none")[:16]))
        want_a = {"A90": 0.90, "A80": 0.80}[arm]
        if f.get("a") is None or abs(float(f.get("a")) - want_a) > 1e-12:
            bad.append("%s: the record holds the scale %s, the card has %.2f" % (nm, f.get("a"), want_a))
        newly[arm] = f.get("n_rows_base_gap_above_60_and_scaled_at_most_60")
    return {"pass": not bad, "failures": bad, "values": {"n_rows_newly_in_range": newly, "counts": rec.get("counts")}}


def ctl_e1(wrapper_sha16, check_text, hashes_text, check_files_present, run_shas):
    """e1 wrapper: the wrapper file has the hash 28bc31f21ecb4ccb; the banked check files are in place, the pod check record ends with `ZZ CHECK-WRAPPER-V PASS` and the hashes name the wrapper; the run text of each of
    the six new runs names a wrapper hash that begins with it"""
    bad = []
    if wrapper_sha16 != WRAPPER_SHA:
        bad.append("the wrapper file is %s, not %s" % (wrapper_sha16, WRAPPER_SHA))
    if not check_files_present:
        bad.append("a banked check file of the wrapper is missing")
    if last_line(check_text).strip() != CHECK_LAST:
        bad.append("the last line of the pod check is %r" % last_line(check_text).strip())
    if WRAPPER_SHA not in (hashes_text or ""):
        bad.append("the pod check hashes do not name %s" % WRAPPER_SHA)
    for k in new_keys():
        v = run_shas.get(k)
        if v is None:
            bad.append("%s: the run text names no wrapper hash" % k)
        elif not v.startswith(WRAPPER_SHA):
            bad.append("%s: the run text names the wrapper hash %s" % (k, v[:16]))
    return {"pass": not bad, "failures": bad, "wrapper_sha16": wrapper_sha16}


